def _sanitize(value):
    """Force every emitted number to be a finite JSON number within 1e8."""
    if isinstance(value, dict):
        return {k: _sanitize(v) for k, v in value.items()}
    if isinstance(value, list):
        return [_sanitize(v) for v in value]
