        return 0.0
    if isinstance(value, float):
        if not np.isfinite(value):
            return 0.0
        if value > VALUE_LIMIT:
            return VALUE_LIMIT
        if value < -VALUE_LIMIT:
            return -VALUE_LIMIT
        if value == 0.0:
            return 0.0
        return value
    if isinstance(value, int):
        if value > VALUE_LIMIT or value < -VALUE_LIMIT:
            return float(value)
        return value
    return value


def _dumps(payload):
